import React, { useState, useEffect } from 'react';
import {
  Box,
  Typography,
  Button,
  CircularProgress,
  Alert,
  useTheme,
  useMediaQuery,
} from '@mui/material';
import { Refresh } from '@mui/icons-material';

const Awards = () => {
  const [awardsData, setAwardsData] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [imageLoadingStates, setImageLoadingStates] = useState({});

  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down('sm'));
  const isTablet = useMediaQuery(theme.breakpoints.down('md'));

  const SCRIPT_URL = 'https://script.google.com/macros/s/AKfycbwqfGaBmESp40RQOJZy_iLH1Q842z9bpi3w8Gg15kYHsrxKior_znz-uJxc5lxZKRFzug/exec';

  const fetchAwardsData = async () => {
    setLoading(true);
    setError(null);
    try {
      console.log('Fetching awards data...');
      const response = await fetch(`${SCRIPT_URL}?t=${Date.now()}`);
      
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }
      
      const result = await response.json();
      console.log('API Response:', result);
      
      if (result.success && result.data) {
        // Map the data to match what your Google Apps Script returns
        const transformedData = result.data.map((item, index) => ({
          awardNo: item.imageNo || index + 1, // Map imageNo to awardNo
          fileName: item.fileName || `Certificate ${item.imageNo || index + 1}`,
          imageUrl: item.imageUrl, // Use imageUrl directly from the script
          description: item.description || '' // Use description from the script
        }));
        
        console.log('Transformed data:', transformedData);
        setAwardsData(transformedData);
        
        const initialLoadingStates = {};
        transformedData.forEach((item, index) => {
          initialLoadingStates[index] = true;
        });
        setImageLoadingStates(initialLoadingStates);
      } else {
        throw new Error(result.error || 'No data received from server');
      }
    } catch (err) {
      console.error('Fetch error:', err);
      setError(`Error loading certificates: ${err.message}`);
    } finally {
      setLoading(false);
    }
  };

  // Get thumbnail URL from image URL
  const getThumbnailUrl = (imageUrl) => {
    if (!imageUrl) return '';
    
    // Extract file ID from the image URL
    const fileId = extractFileId(imageUrl);
    if (fileId) {
      return `https://drive.google.com/thumbnail?id=${fileId}&sz=w400`;
    }
    
    return imageUrl;
  };

  // Extract file ID from Google Drive URL
  const extractFileId = (url) => {
    if (!url) return '';
    
    if (url.includes('/uc?id=')) {
      return url.split('/uc?id=')[1]?.split('&')[0];
    } else if (url.includes('/file/d/')) {
      return url.split('/file/d/')[1]?.split('/')[0];
    } else if (url.includes('id=')) {
      return url.split('id=')[1]?.split('&')[0];
    }
    
    return '';
  };

  const handleImageLoad = (index) => {
    setImageLoadingStates(prev => ({
      ...prev,
      [index]: false
    }));
  };

  const handleImageError = (index, url) => {
    console.error(`Failed to load image ${index}:`, url);
    setImageLoadingStates(prev => ({
      ...prev,
      [index]: false
    }));
  };

  // Determine columns based on screen size
  const getColumns = () => {
    if (isMobile) return 2;
    if (isTablet) return 3;
    return 4;
  };

  useEffect(() => {
    fetchAwardsData();
  }, []);

  if (loading) {
    return (
      <Box 
        display="flex" 
        justifyContent="center" 
        alignItems="center" 
        minHeight="200px"
        flexDirection="column"
        gap={2}
      >
        <CircularProgress />
        <Typography variant="body1">Loading certificates...</Typography>
      </Box>
    );
  }

  if (error) {
    return (
      <Box p={3} display="flex" flexDirection="column" alignItems="center" gap={2}>
        <Alert severity="error" sx={{ width: '100%', maxWidth: 400 }}>
          {error}
        </Alert>
        <Button 
          variant="contained" 
          startIcon={<Refresh />}
          onClick={fetchAwardsData}
        >
          Try Again
        </Button>
      </Box>
    );
  }

  return (
    <Box sx={{ p: { xs: 1, sm: 2, md: 3 }, maxWidth: 1200, margin: '0 auto' }}>
      <Typography 
        variant="h4" 
        component="h1" 
        align="center" 
        gutterBottom 
        sx={{ 
          fontSize: { xs: '1.75rem', sm: '2.5rem', md: '3rem' },
          mb: 1 
        }}
      >
        Awards & Certificates
      </Typography>
      
      <Typography 
        variant="h6" 
        component="p" 
        align="center" 
        color="text.secondary"
        sx={{ mb: 3 }}
      >
        {awardsData.length} {awardsData.length === 1 ? 'certificate' : 'certificates'}
      </Typography>

      {awardsData.length === 0 ? (
        <Box textAlign="center" p={3}>
          <Typography variant="body1" color="text.secondary" gutterBottom>
            No certificates found.
          </Typography>
          <Button 
            variant="outlined" 
            startIcon={<Refresh />}
            onClick={fetchAwardsData}
            sx={{ mt: 2 }}
          >
            Refresh
          </Button>
        </Box>
      ) : (
        <Box
          sx={{
            columnCount: getColumns(),
            columnGap: 1,
            '& > *': {
              breakInside: 'avoid',
              marginBottom: 1,
              display: 'inline-block',
              width: '100%',
            }
          }}
        >
          {awardsData.map((item, idx) => {
            const thumbnailUrl = getThumbnailUrl(item.imageUrl);
            
            return (
              <Box
                key={idx}
                sx={{
                  borderRadius: 2,
                  overflow: 'hidden',
                  boxShadow: 1,
                  transition: 'all 0.3s ease',
                  backgroundColor: 'background.paper',
                  '&:hover': {
                    transform: 'translateY(-4px)',
                    boxShadow: 4,
                  },
                  position: 'relative',
                  display: 'inline-block',
                  width: '100%',
                }}
              >
                {/* Loader - Only show while image is loading */}
                {imageLoadingStates[idx] && (
                  <Box
                    sx={{
                      position: 'absolute',
                      top: 0,
                      left: 0,
                      right: 0,
                      bottom: 0,
                      display: 'flex',
                      alignItems: 'center',
                      justifyContent: 'center',
                      backgroundColor: 'rgba(0,0,0,0.05)',
                      zIndex: 1,
                      minHeight: 200,
                    }}
                  >
                    <CircularProgress size={40} />
                  </Box>
                )}
                
                <Box
                  component="img"
                  src={thumbnailUrl}
                  alt={item.fileName}
                  loading="lazy"
                  sx={{
                    width: '100%',
                    height: 'auto',
                    display: 'block',
                    opacity: imageLoadingStates[idx] ? 0 : 1,
                    transition: 'opacity 0.3s ease',
                    minHeight: 200,
                    objectFit: 'cover'
                  }}
                  onLoad={() => handleImageLoad(idx)}
                  onError={() => handleImageError(idx, thumbnailUrl)}
                />

                {/* Description overlay */}
                {item.description && (
                  <Box
                    sx={{
                      position: 'absolute',
                      bottom: 0,
                      left: 0,
                      right: 0,
                      background: 'linear-gradient(transparent, rgba(0,0,0,0.7))',
                      color: 'white',
                      p: 2,
                      opacity: 0,
                      transition: 'opacity 0.3s ease',
                      '&:hover': {
                        opacity: 1,
                      },
                    }}
                  >
                    <Typography variant="body2" sx={{ fontSize: '0.8rem' }}>
                      {item.description}
                    </Typography>
                  </Box>
                )}

                {/* File name overlay */}
                <Box
                  sx={{
                    position: 'absolute',
                    top: 0,
                    left: 0,
                    right: 0,
                    background: 'linear-gradient(rgba(0,0,0,0.5), transparent)',
                    color: 'white',
                    p: 1,
                    opacity: 0.8,
                  }}
                >
                  <Typography variant="caption" noWrap sx={{ fontSize: '0.7rem' }}>
                    {item.fileName}
                  </Typography>
                </Box>
              </Box>
            );
          })}
        </Box>
      )}
    </Box>
  );
};

export default Awards;
